    private static int func(int element, int k)
    {
        TrieNode cur = root;
        int maxInd = -1;
        for(int i = 29; i >= 0 && cur != null; i--)
        {
            // What value must this node be to ensure that the xor of this(whatever number we are building, let's call it 'a') and element will be >= k
            int kBit = (k & (1 << i)) > 0 ? 1 : 0;
            int elementBit = (element & (1 << i)) > 0 ? 1 : 0;
            // Let's make some cases for the values of 'kBit' and 'elementBit'
            // (kBit, elementBit)
            // Case 01: (0, 0) -> Means that we need the xor of the elementBit and 'a''s current bit to be 0, if it is a 1, then also it works, cause still the value of element ^ a >= k. But what this means for the value of this function? We are trying to find the largest index that can withhold (element ^ a) >= k. If we go down the trie following the 1 bit route, it will definitely fetch us a result(which might even be the largest index), but what if there was an index larger than that and it had a 0 bit in this place, cause that would also maintain element ^ a >= k, how can we make sure that we do not miss such values?
