            // Case 02: (0, 1) -> Means that again we can allow any bit here. Now which one to take? Taking a 0 will make this number go ahead of what we need and thus definitely fetch us a number 'a', hence by similar logic as Case 01, we shall store the value obtained at bit 0 and follow the path of bit 1.
            // Case 03: (1, 0) -> We definitely need a 1 bit -> no other choice
            // Case 04: (1, 1) -> We definitely need a 0 bit -> no other choice
            if(kBit == 0)
            {
                if(elementBit == 0)
                {
                    // Case 01
                    if(cur.contains(1))
                        maxInd = Math.max(maxInd, cur.get(1).lastInd);
                    cur = cur.get(0);
                }
                else
                {
                    // Case 02
                    if(cur.contains(0))
                        maxInd = Math.max(maxInd, cur.get(0).lastInd);
                    cur = cur.get(1);           
                }
            }
            else
                cur = cur.get(elementBit ^ 1);
        }
        if(cur != null)
            maxInd = Math.max(maxInd, cur.lastInd);
        return maxInd;
    }

    private static void insert(int num, int ind)
    {
        TrieNode cur = root;
