#include<bits/stdc++.h>
#define ll long long
using namespace std;

ll cal(vector<ll> & ai, ll las, ll k){
	ll ans = ai.size() + 1;
	map<ll, ll> cnt;
	for(ll i = 0; i < ai.size(); i++){
		ll x = (ai[i] >> las) & 1;
		ll st = 1;
		if(x){
			for(ll j = las - 1; j >= 0; j--){
				ll x1 = (k >> j) & 1;
				ll ta = (ai[i] >> j) & 1;
				if(x1){
					st = ((st << 1) | (1 ^ ta));
				}
				else{
					ll tem = ((st << 1) | (1 ^ ta));
					if(cnt[tem])ans = min(ans, i - cnt[tem] + 2);
					st = ((st << 1) | ta);
				}
			}
			if(cnt[st])ans = min(ans, i - cnt[st] + 2);
		}
		else{
			for(ll j = las - 1; j >= 0; j--){
			    ll ta = (ai[i] >> j) & 1;
			    st = (st << 1) | ta;
			    cnt[st] = i + 1;
			}
		}
	}
	return ans;
}

